// Exact PDF templates for document creation (docs/doccreation/
// pdf-templates-contract.md): the Word path is gone; a template is the
// uploaded PDF itself plus an overlay of fill-in regions.
//
// Every PDF here is REAL and generated by the spec (e2e/fixtures/pdf-form.js):
// a two-page "Employee details" form with a raster logo, underscore leaders,
// boxes, a photo box and a large notes box — blank, and the same form filled
// with known values (FORM_VALUES) and a photo.
//
//   PDF-01 blank flow: upload -> editor shows the page and the detected
//          regions -> move + resize one, draw a new one -> confirm -> Ready
//   PDF-02 filled flow: removed values shown for review; restore the
//          low-confidence one and remove it again by drawing -> confirm ->
//          the template renders pixel-identical to the blank twin
//   PDF-03 document: type on the page (autosave), photos (auto-fill, drag
//          onto the box = swap), long notes -> overflow -> generate (+1 page)
//          -> download: typed values in the PDF, page count = template + 1
//   PDF-04 release: submit -> a second (approver) user releases; the
//          review file is the PDF
//   PDF-05 DOCX refused; the legacy Word purge answers counts
//   PDF-06 AI unavailable (fake LLM error500): the filled upload still
//          works from code alone (detectedBy CODE) and gives the same template
//
// All of it runs with the fake LLM in its default mode (which answers the
// template prompts with nothing usable), i.e. the code path delivers the
// feature; PDF-06 then takes the model away entirely.
//
// UI contract (frontend/src/pages/Blueprint*Page, DocInstancesPage,
// DocBuilderPage, components/pdf/*): data-testid page-view (the page image +
// overlay), region-<key> (editor box; corner handles [data-handle=se|…]),
// region-properties, edit-list, checklist; edit boxes carry
// data-edit-kind / data-low-confidence. Builder: field-<key> (the input on
// the page), photo-box-<key>, photo-tray, overflow-<key>, save-state.
// Tools are buttons in role=toolbar "Editing tools"; pages are buttons
// "Page N[, …]" in nav "Pages"; the side panel is region "Fields".
import { test, expect, openAs } from '../../lib/fixtures.js';
import { BOOTSTRAP, OPERATOR, uniqueName } from '../../lib/seed.js';
import { seedLegacyWordTemplate } from '../../lib/db.js';
import { employeeForm, FORM_VALUES } from '../../fixtures/pdf-form.js';
import { decodePng, inkInBox, photoPng } from '../../fixtures/png.js';
import { containsText, pageContents, pageCount, pageTexts } from '../../lib/pdf-inspect.js';
import {
  blueprintFile,
  confirmAsProposed,
  expectSameRendering,
  fakeDocx,
  getBlueprint,
  getBytes,
  uploadBlueprint,
} from '../../lib/doccreation.js';

const BLANK_PDF = employeeForm({ filled: false });
const FILLED_PDF = employeeForm({ filled: true });
const TEMPLATE_PAGES = 2;
const SAMPLE_VALUES = Object.values(FORM_VALUES);

// What the operator types into the new document.
const DOC = {
  fullName: 'Jane Doe',
  employeeId: 'EMP-77310',
  department: 'Operations',
  managerName: 'Alex Manager',
  dateOfBirth: '1990-04-12',
  // Far more than the 450 x 60 pt notes box takes even at the minimum size.
  notes: Array.from(
    { length: 40 },
    (_, i) => `Note ${i + 1}: the applicant moved teams and the details above were checked against the HR record.`
  ).join(' '),
};

test.describe.configure({ mode: 'serial' });

/** Opens the upload card on /creation/blueprints (it opens by itself only when the list is empty). */
async function openTemplateUpload(page) {
  const heading = page.getByRole('heading', { name: 'Upload a template', level: 2 });
  await expect(async () => {
    if (!(await heading.isVisible())) {
      await page.getByRole('button', { name: 'Upload a template' }).click({ timeout: 2000 });
    }
    await expect(heading).toBeVisible({ timeout: 2000 });
  }).toPass({ timeout: 30_000 });
}

/** Uploads a PDF through the list page and waits for the editor. Returns the blueprint id. */
async function uploadThroughUi(page, { bytes, fileName, name, flowLabel }) {
  await openAs(page, OPERATOR(), '/creation/blueprints');
  await openTemplateUpload(page);
  await page.getByLabel('PDF file').setInputFiles({ name: fileName, mimeType: 'application/pdf', buffer: bytes });
  await page.getByPlaceholder('e.g. Loan application').fill(name);
  if (flowLabel) await page.getByRole('radio', { name: flowLabel }).check();
  await page.getByRole('button', { name: 'Upload and review' }).click();
  await expect(page).toHaveURL(/\/creation\/blueprints\/\d+$/, { timeout: 60_000 });
  return Number(new URL(page.url()).pathname.split('/').pop());
}

/** The page image shown by a PageView has really loaded (a server-rendered PNG). */
async function expectPageImageLoaded(page) {
  const image = page.getByTestId('page-view').locator('img').first();
  await expect(image).toBeVisible();
  await expect.poll(() => image.evaluate((img) => img.complete && img.naturalWidth)).toBeGreaterThan(100);
}

/** Drags with the mouse between two points given as page fractions of the PageView. */
async function dragOnPage(page, from, to) {
  const view = page.getByTestId('page-view');
  // The page is taller than the viewport: centre it, so the middle band is on screen.
  await view.evaluate((el) => el.scrollIntoView({ block: 'center' }));
  const box = await view.boundingBox();
  for (const [, fy] of [from, to]) {
    const y = box.y + fy * box.height;
    expect(y > 120 && y < page.viewportSize().height, `fraction ${fy} is on screen`).toBe(true);
  }
  const at = ([fx, fy]) => [box.x + fx * box.width, box.y + fy * box.height];
  const [x0, y0] = at(from);
  const [x1, y1] = at(to);
  await page.mouse.move(x0, y0);
  await page.mouse.down();
  await page.mouse.move((x0 + x1) / 2, (y0 + y1) / 2, { steps: 4 });
  await page.mouse.move(x1, y1, { steps: 4 });
  await page.mouse.up();
}

/** Drags an element's centre by (dx, dy) CSS pixels. */
async function dragBy(page, locator, dx, dy) {
  await locator.evaluate((el) => el.scrollIntoView({ block: 'center' }));
  const box = await locator.boundingBox();
  const x = box.x + box.width / 2;
  const y = box.y + box.height / 2;
  await page.mouse.move(x, y);
  await page.mouse.down();
  await page.mouse.move(x + dx / 2, y + dy / 2, { steps: 4 });
  await page.mouse.move(x + dx, y + dy, { steps: 4 });
  await page.mouse.up();
}

const near = (a, b, tolerance = 0.002) => Math.abs(a - b) <= tolerance;

test.describe('exact PDF templates @phase2 @pdf', () => {
  let blankId;
  let blankName;
  let filledId;
  let instanceId;
  let instanceTitle;

  test('PDF-01 blank flow: the PDF is the template; regions are detected, edited, drawn and confirmed', async ({
    page,
    operatorApi,
  }) => {
    blankName = uniqueName('E2E Employee form');
    blankId = await uploadThroughUi(page, {
      bytes: BLANK_PDF,
      fileName: 'employee-form.pdf',
      name: blankName,
      flowLabel: /Blank template/,
    });

    // The editor: the real page image with the detected regions on top.
    await expect(page.getByRole('heading', { name: blankName })).toBeVisible();
    await expect(page.getByText('Review the proposed template')).toBeVisible();
    await expectPageImageLoaded(page);
    const proposed = await getBlueprint(operatorApi, blankId);
    expect(proposed).toMatchObject({ status: 'DRAFT', flow: 'BLANK' });
    expect(proposed.pages).toHaveLength(TEMPLATE_PAGES);
    const byKey = Object.fromEntries(proposed.regions.map((r) => [r.key, r]));
    // Code detection: leaders, boxes, the photo box, the signature/date lines, the notes box.
    expect(byKey).toMatchObject({
      full_name: { kind: 'TEXT', page: 0 },
      date_of_birth: { kind: 'DATE', page: 0 },
      employee_id: { kind: 'TEXT', page: 0 },
      department: { kind: 'TEXT', page: 0 },
      photo: { kind: 'IMAGE', page: 0 },
      signature: { kind: 'SIGNATURE', page: 0 },
      notes: { kind: 'MULTILINE', page: 1 },
    });
    expect(proposed.edits).toEqual([]);
    for (const key of ['full_name', 'date_of_birth', 'employee_id', 'department', 'photo', 'signature']) {
      await expect(page.getByTestId(`region-${key}`)).toBeVisible();
    }
    await expect(page.getByRole('button', { name: /^Page 2, 1 field$/ })).toBeVisible();

    // Move the department box, then resize it from its bottom-right corner.
    const department = page.getByTestId('region-department');
    const before = await department.boundingBox();
    await dragBy(page, department, -24, 12);
    await expect
      .poll(async () => (await department.boundingBox()).x)
      .toBeLessThan(before.x - 15);
    await expect(department).toHaveAttribute('aria-pressed', 'true');
    const moved = await department.boundingBox();
    await dragBy(page, department.locator('[data-handle="se"]'), 30, 10);
    await expect
      .poll(async () => (await department.boundingBox()).width)
      .toBeGreaterThan(moved.width + 20);
    await expect(page.getByText(/Unsaved changes/)).toBeVisible();

    // Draw a new field in the empty band under the signature lines and name it.
    await page.getByRole('toolbar', { name: 'Editing tools' }).getByRole('button', { name: 'Add field' }).click();
    await dragOnPage(page, [0.12, 0.45], [0.45, 0.475]);
    const properties = page.getByTestId('region-properties');
    await expect(properties).toBeVisible();
    await properties.getByLabel('Label').fill('Manager name');
    await expect(properties.getByLabel('Key')).toHaveValue('manager_name');
    await expect(page.getByTestId('region-manager_name')).toBeVisible();

    await page.getByRole('button', { name: 'Confirm template' }).click();
    await expect(page.getByText('Template confirmed — it is ready for new documents')).toBeVisible();
    await expect(page.getByText(/· version 1$/)).toBeVisible();

    const saved = await getBlueprint(operatorApi, blankId);
    expect(saved).toMatchObject({ status: 'READY', version: 1, currentVersion: 1 });
    const savedByKey = Object.fromEntries(saved.regions.map((r) => [r.key, r]));
    expect(savedByKey.manager_name).toMatchObject({ kind: 'TEXT', page: 0, source: 'MANUAL' });
    expect(near(savedByKey.manager_name.fx, 0.12, 0.01)).toBe(true);
    const was = byKey.department;
    const now = savedByKey.department;
    expect(now.fx).toBeLessThan(was.fx - 0.005);
    expect(now.fw).toBeGreaterThan(was.fw + 0.005);
    expect(now.fh).toBeGreaterThan(was.fh);
    // Blank flow: the template PDF is the uploaded PDF, byte for byte.
    expect((await blueprintFile(operatorApi, blankId)).equals(BLANK_PDF)).toBe(true);

    await page.goto('/creation/blueprints');
    const row = page.getByRole('row').filter({ has: page.getByRole('link', { name: blankName }) });
    await expect(row.getByText('Ready')).toBeVisible();
  });

  test('PDF-02 filled flow: the data is removed for review; the template equals the blank form pixel for pixel', async ({
    page,
    operatorApi,
  }) => {
    test.skip(!blankId, 'needs the blank template from PDF-01');
    const name = uniqueName('E2E Employee form from data');
    await openAs(page, OPERATOR(), '/creation/blueprints');
    await openTemplateUpload(page);
    // A "_filled" file name suggests the data flow by itself.
    await page.getByLabel('PDF file').setInputFiles({
      name: 'employee_filled.pdf',
      mimeType: 'application/pdf',
      buffer: FILLED_PDF,
    });
    await expect(page.getByRole('radio', { name: /Filled document/ })).toBeChecked();
    await page.getByPlaceholder('e.g. Loan application').fill(name);
    await page.getByRole('button', { name: 'Upload and review' }).click();
    await expect(page).toHaveURL(/\/creation\/blueprints\/\d+$/, { timeout: 60_000 });
    filledId = Number(new URL(page.url()).pathname.split('/').pop());
    await expect(page.getByText(/marked for removal \(hatched boxes\)/)).toBeVisible();
    await expectPageImageLoaded(page);

    const draft = await getBlueprint(operatorApi, filledId);
    expect(draft).toMatchObject({ status: 'DRAFT', flow: 'WITH_DATA' });
    const removed = draft.edits.filter((e) => e.kind === 'REMOVE').map((e) => e.removedText);
    for (const value of SAMPLE_VALUES) expect(removed).toContain(value);
    expect(removed).toContain('[image]'); // the photo in the photo box
    expect(draft.regions.find((r) => r.key === 'full_name')?.sampleValue).toBe(FORM_VALUES.fullName);

    // Every removal is listed with the value it removes.
    const editList = page.getByTestId('edit-list');
    await expect(page.getByRole('heading', { name: `Template changes (${draft.edits.length})` })).toBeVisible();
    for (const value of SAMPLE_VALUES) {
      await expect(editList.getByText(`Removed content: “${value}”`, { exact: false })).toBeVisible();
    }

    // The free-standing e-mail is only a guess: low confidence, flagged for review.
    const low = draft.edits.find((e) => e.removedText === FORM_VALUES.contact);
    expect(low.confidence).toBeLessThan(0.6);
    await expect(page.getByTestId('checklist')).toContainText(
      `Check the removal of “${FORM_VALUES.contact}” on page 2 (low confidence)`
    );
    await page.getByRole('button', { name: /^Page 2\b/ }).click();
    await expect(page.locator('[data-edit-kind="REMOVE"][data-low-confidence="true"]')).toBeVisible();

    // Restore it (the value stays in the template) ...
    await page.getByRole('button', { name: `Restore: Removed content: “${FORM_VALUES.contact}” on page 2` }).click();
    await expect(page.getByRole('heading', { name: `Template changes (${draft.edits.length - 1})` })).toBeVisible();
    await expect(page.locator('[data-low-confidence="true"][data-edit-kind="REMOVE"]')).toHaveCount(0);
    // ... then change our mind: draw a removal box over it again.
    await page.getByRole('toolbar', { name: 'Editing tools' }).getByRole('button', { name: 'Remove content' }).click();
    const pad = 0.006;
    await dragOnPage(page, [low.fx - pad, low.fy - pad], [low.fx + low.fw + pad, low.fy + low.fh + pad]);
    await expect(page.getByRole('heading', { name: `Template changes (${draft.edits.length})` })).toBeVisible();

    await page.getByRole('button', { name: 'Confirm template' }).click();
    await expect(page.getByText('Template confirmed — it is ready for new documents')).toBeVisible();

    const saved = await getBlueprint(operatorApi, filledId);
    expect(saved.status).toBe('READY');
    expect(saved.edits).toHaveLength(draft.edits.length);
    expect(saved.edits.filter((e) => e.source === 'USER')).toHaveLength(1);
    // Review data (customer values) is gone once the template is confirmed.
    expect(saved.regions.every((r) => r.sampleValue == null)).toBe(true);
    expect(saved.edits.every((e) => e.removedText == null)).toBe(true);

    // The proof: the template made from the FILLED form renders exactly like the BLANK form.
    await expectSameRendering(operatorApi, blankId, filledId, TEMPLATE_PAGES);
    // ... and its PDF no longer carries the sample values, while the form's own text is intact.
    const templatePdf = await blueprintFile(operatorApi, filledId);
    const templateText = pageTexts(templatePdf).join('\n');
    expect(templateText).toContain('Employee Details Form');
    expect(templateText).toContain('Thank you for keeping your details up to date.');
    for (const value of SAMPLE_VALUES) expect(templateText).not.toContain(value);
    // Not even the removed values' glyph widths (BUG-PDF-02): no TJ made of advances only.
    for (const content of pageContents(templatePdf)) {
      expect(content).not.toMatch(/\[\s*(?:-?\d+(?:\.\d+)?\s*)+\]\s*TJ/);
    }
    // The original upload is kept unchanged (audit / "show original").
    expect((await blueprintFile(operatorApi, filledId, 'original')).equals(FILLED_PDF)).toBe(true);
  });

  // BUG-PDF-01: a low-confidence guess (confidence < 0.6, e.g. a free-standing
  // e-mail or date that may be static form text) is APPLIED by default: the
  // upload already cuts it from the draft template (DocBlueprintUseCase.create
  // applies every proposed removal) and the editor sends it on "Confirm
  // template" unless the user restores it. The plan says low-confidence
  // results are "shown for review instead of being applied" (the engine's
  // own corpus harness, CorpusSupport.applied, accepts only >= 0.6 by
  // default). Expected: confirming without review keeps such text.
  test.fixme('PDF-02b BUG-PDF-01 confirming a filled upload without review keeps the low-confidence guesses', async ({
    page,
    operatorApi,
  }) => {
    const id = await uploadThroughUi(page, {
      bytes: FILLED_PDF,
      fileName: 'employee_filled.pdf',
      name: uniqueName('E2E unreviewed'),
      flowLabel: /Filled document/,
    });
    const draft = await getBlueprint(operatorApi, id);
    const low = draft.edits.find((e) => e.removedText === FORM_VALUES.contact);
    expect(low.confidence).toBeLessThan(0.6);
    await page.getByRole('button', { name: 'Confirm template' }).click();
    await expect(page.getByText('Template confirmed — it is ready for new documents')).toBeVisible();
    const templateText = pageTexts(await blueprintFile(operatorApi, id)).join('\n');
    expect(templateText).toContain(FORM_VALUES.contact);
  });

  test('PDF-03 a document is filled on the page, gets photos, overflows to an added page and downloads as PDF', async ({
    page,
    operatorApi,
  }) => {
    test.skip(!blankId, 'needs the template from PDF-01');
    instanceTitle = uniqueName('E2E Employee record');
    await openAs(page, OPERATOR(), '/creation/documents');
    const heading = page.getByRole('heading', { name: 'New document', level: 2 });
    await expect(async () => {
      if (!(await heading.isVisible())) await page.getByRole('button', { name: 'New document' }).click({ timeout: 2000 });
      await expect(heading).toBeVisible({ timeout: 2000 });
    }).toPass({ timeout: 30_000 });
    await page.getByLabel('Template').selectOption({ label: `${blankName} (2 pages)` });
    await expect(page.getByRole('img', { name: `Page 1 of ${blankName}` })).toBeVisible();
    await page.getByPlaceholder(/Survey/).fill(instanceTitle);
    await page.getByRole('button', { name: 'Create document' }).click();
    await expect(page).toHaveURL(/\/creation\/documents\/\d+$/);
    instanceId = Number(new URL(page.url()).pathname.split('/').pop());

    // The template page, exactly, with inputs on its regions.
    await expect(page.getByRole('heading', { name: instanceTitle })).toBeVisible();
    await expectPageImageLoaded(page);
    const onPage = (key, tag = 'input') => page.getByTestId(`field-${key}`).locator(tag);
    await onPage('full_name').fill(DOC.fullName);
    await onPage('employee_id').fill(DOC.employeeId);
    await onPage('department').fill(DOC.department);
    await onPage('manager_name').fill(DOC.managerName);
    await expect(onPage('date_of_birth')).toHaveAttribute('type', 'date');
    await onPage('date_of_birth').fill(DOC.dateOfBirth);
    await expect(page.getByTestId('save-state')).toHaveText('Saved');
    // The side panel edits the same values.
    const fieldsPanel = page.getByRole('region', { name: 'Fields' });
    // (its accessible name keeps label and page note apart: "Full name page 1", not "Full namepage 1")
    await expect(fieldsPanel.getByRole('textbox', { name: 'Full name page 1', exact: true })).toHaveValue(DOC.fullName);
    const afterTyping = await operatorApi.get(`/api/doccreation/instances/${instanceId}`);
    expect(afterTyping.values).toMatchObject({
      full_name: DOC.fullName,
      employee_id: DOC.employeeId,
      department: DOC.department,
      manager_name: DOC.managerName,
    });

    // Photos: upload two at once with auto-fill; the one named like the box goes in.
    await page.getByLabel('Choose photos').setInputFiles([
      { name: 'photo-jane.png', mimeType: 'image/png', buffer: photoPng(60, 80, [30, 90, 160]) },
      { name: 'extra-shot.png', mimeType: 'image/png', buffer: photoPng(60, 80, [160, 40, 40]) },
    ]);
    await page.getByRole('button', { name: 'Auto-fill photos' }).click();
    await expect(page.getByText('1 placed in photo boxes, 1 in the tray')).toBeVisible();
    const photoBox = page.getByTestId('photo-box-photo');
    await expect(photoBox.getByRole('img', { name: 'Photo: photo-jane.png' })).toBeVisible();
    const tray = page.getByTestId('photo-tray');
    await expect(tray.getByText('extra-shot.png')).toBeVisible();

    // Drag the tray photo onto the filled box: they swap.
    // (grabbed by its thumbnail: the rest of the tray row is the "Place in…" select)
    await tray.getByRole('img', { name: 'extra-shot.png' }).dragTo(photoBox);
    await expect(page.getByText('Photo placed in “Photo” (swapped)')).toBeVisible();
    await expect(photoBox.getByRole('img', { name: 'Photo: extra-shot.png' })).toBeVisible();
    await expect(tray.getByText('photo-jane.png')).toBeVisible();
    const afterSwap = await operatorApi.get(`/api/doccreation/instances/${instanceId}`);
    const placed = Object.fromEntries(afterSwap.images.map((i) => [i.originalName, i.regionKey]));
    expect(placed).toEqual({ 'extra-shot.png': 'photo', 'photo-jane.png': null });

    // Page 2: long notes do not fit the box even at the minimum size.
    await page.getByRole('button', { name: /^Page 2\b/ }).click();
    await onPage('notes', 'textarea').fill(DOC.notes);
    await expect(page.getByTestId('overflow-notes')).toHaveText('Will continue on an added page');
    await expect(page.getByTestId('save-state')).toHaveText('Saved');
    expect((await operatorApi.get(`/api/doccreation/instances/${instanceId}`)).overflow).toEqual(['notes']);

    // Generate: one page added for the notes, and the layout verified exact.
    const generated = page.waitForResponse((r) => r.url().endsWith(`/instances/${instanceId}/generate`));
    await page.getByRole('button', { name: 'Generate' }).click();
    const result = await (await generated).json();
    expect(result).toMatchObject({ pdfReady: true, addedPages: 1, exact: true });
    await expect(
      page.getByText('PDF generated — 1 page added for text that did not fit (Notes) · layout verified exact')
    ).toBeVisible();

    // Download through the UI and read the PDF.
    const downloadEvent = page.waitForEvent('download');
    await page.getByRole('button', { name: 'Download PDF' }).click();
    const download = await downloadEvent;
    expect(download.suggestedFilename()).toMatch(/\.pdf$/);
    const pdf = await (await import('node:fs/promises')).readFile(await download.path());
    expect(pdf.subarray(0, 5).toString('latin1')).toBe('%PDF-');
    expect(pageCount(pdf)).toBe(TEMPLATE_PAGES + 1);
    const pages = pageTexts(pdf);
    for (const value of [DOC.fullName, DOC.dateOfBirth, DOC.employeeId, DOC.department, DOC.managerName]) {
      expect(containsText(pages[0], value), `page 1 shows "${value}"`).toBe(true);
    }
    expect(pages[0]).toContain('Employee Details Form');
    expect(containsText(pages[1], '(continued on page 3)')).toBe(true);
    expect(containsText(pages[2], 'Note 1: the applicant moved teams')).toBe(true);
    expect(containsText(pages[2], 'Note 40: the applicant moved teams')).toBe(true);

    // The photo is drawn into the photo box (the blank box is white inside).
    const template = await getBlueprint(operatorApi, blankId);
    const photoRegion = template.regions.find((r) => r.key === 'photo');
    const inner = {
      fx: photoRegion.fx + photoRegion.fw * 0.2,
      fy: photoRegion.fy + photoRegion.fh * 0.2,
      fw: photoRegion.fw * 0.6,
      fh: photoRegion.fh * 0.6,
    };
    const preview = await getBytes(operatorApi, `/api/doccreation/instances/${instanceId}/pages/0`);
    expect(preview.status).toBe(200);
    const blankPage = await getBytes(operatorApi, `/api/doccreation/blueprints/${blankId}/pages/0?variant=template`);
    expect(inkInBox(decodePng(blankPage.bytes), inner)).toBe(0);
    expect(inkInBox(decodePng(preview.bytes), inner)).toBeGreaterThan(100);
  });

  test('PDF-04 release: the author submits, a second user releases; the review file is the PDF', async ({
    page,
    operatorApi,
    adminApi,
  }) => {
    test.skip(!instanceId, 'needs the generated document from PDF-03');
    await openAs(page, OPERATOR(), `/creation/documents/${instanceId}`);
    await page.getByRole('button', { name: 'Submit for release' }).click();
    await expect(page.getByText('Submitted — an approver (not you) can now release it')).toBeVisible();
    expect((await operatorApi.get(`/api/doccreation/instances/${instanceId}`)).status).toBe('SUBMITTED');
    // The author cannot release their own document.
    expect((await operatorApi.request('POST', `/api/doccreation/instances/${instanceId}/release`, { json: {} })).status).toBe(403);

    const review = await getBytes(adminApi, `/api/doccreation/instances/${instanceId}/review-file`);
    expect(review.status).toBe(200);
    expect(review.contentType).toContain('application/pdf');
    expect(review.bytes.subarray(0, 5).toString('latin1')).toBe('%PDF-');
    expect(pageCount(review.bytes)).toBe(TEMPLATE_PAGES + 1);
    expect(containsText(pageTexts(review.bytes)[0], DOC.fullName)).toBe(true);

    await openAs(page, BOOTSTRAP(), '/approvals/releases');
    // The queue entry: its comment box sits in the entry's card, next to Release.
    const card = page
      .getByLabel(`Review comment for document ${instanceId}`)
      .locator(`xpath=ancestor::*[contains(., "#${instanceId} · ")][1]`);
    await expect(card.getByText(`Full name: ${DOC.fullName}`)).toBeVisible();
    await card.getByRole('button', { name: 'Release' }).click();
    await expect(page.getByText(`"${instanceTitle}" released`)).toBeVisible();
    expect((await operatorApi.get(`/api/doccreation/instances/${instanceId}`)).status).toBe('RELEASED');
  });

  test('PDF-05 Word files are refused and the legacy Word purge answers counts', async ({ page, operatorApi, adminApi }) => {
    // The upload form refuses a .docx before sending it.
    await openAs(page, OPERATOR(), '/creation/blueprints');
    await openTemplateUpload(page);
    await page.getByLabel('PDF file').setInputFiles({
      name: 'letter.docx',
      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      buffer: fakeDocx(),
    });
    await expect(page.getByRole('alert').filter({ hasText: '“letter.docx” is not a PDF' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Upload and review' })).toBeDisabled();

    // The API checks the bytes, whatever the name says.
    for (const fileName of ['letter.docx', 'renamed.pdf']) {
      const refused = await uploadBlueprint(operatorApi, { bytes: fakeDocx(), fileName, flow: 'BLANK' });
      expect(refused.status, fileName).toBe(400);
      expect(refused.body).toMatchObject({ code: 'NOT_A_PDF' });
    }
    // The Word-path routes are gone.
    if (blankId) {
      for (const route of [`/blueprints/${blankId}/sections`, `/blueprints/${blankId}/paragraphs`]) {
        const gone = await operatorApi.request('GET', `/api/doccreation${route}`);
        expect([404, 405], route).toContain(gone.status);
      }
    }

    // A Word template left from before the upgrade (seeded: the product cannot make one any more)
    // is no longer listed or opened ...
    const legacyName = uniqueName('E2E legacy Word template');
    const legacy = await seedLegacyWordTemplate({ ownerEmail: OPERATOR(), name: legacyName });
    const listed = await operatorApi.get('/api/doccreation/blueprints');
    expect(listed.map((b) => b.name)).not.toContain(legacyName);
    const opened = await operatorApi.request('GET', `/api/doccreation/blueprints/${legacy.blueprintId}`);
    expect(opened.status).toBe(410);
    expect(opened.body).toMatchObject({ code: 'LEGACY_TEMPLATE' });
    const openedDoc = await operatorApi.request('GET', `/api/doccreation/instances/${legacy.instanceId}`);
    expect(openedDoc.status).toBe(410);

    // ... and the one-off purge (bank admins only) removes it with its document and files.
    expect((await operatorApi.request('POST', '/api/admin/doccreation/purge-legacy')).status).toBe(403);
    const purged = await adminApi.request('POST', '/api/admin/doccreation/purge-legacy', { expect: 200 });
    expect(purged.body.blueprints).toBeGreaterThanOrEqual(1);
    expect(purged.body.instances).toBeGreaterThanOrEqual(1);
    expect(purged.body.files).toBeGreaterThanOrEqual(2); // the .docx and the generated export
    expect((await operatorApi.request('GET', `/api/doccreation/blueprints/${legacy.blueprintId}`)).status).toBe(404);
    // Idempotent: nothing is left for a second run.
    const again = await adminApi.request('POST', '/api/admin/doccreation/purge-legacy', { expect: 200 });
    expect(again.body).toEqual({ blueprints: 0, instances: 0, files: 0 });
    // PDF templates are never touched by it.
    if (blankId) expect((await getBlueprint(operatorApi, blankId)).status).toBe('READY');
  });

  test('PDF-06 with the AI unavailable the filled upload works from code alone and gives the same template', async ({
    page,
    operatorApi,
    llm,
  }) => {
    test.skip(!blankId, 'needs the blank template from PDF-01');
    await llm.reset();
    await llm.setMode('error500');
    const name = uniqueName('E2E Employee form without AI');
    const id = await uploadThroughUi(page, {
      bytes: FILLED_PDF,
      fileName: 'employee_filled.pdf',
      name,
      flowLabel: /Filled document/,
    });
    await expect(page.getByText('(found by rules)')).toBeVisible();
    const draft = await getBlueprint(operatorApi, id);
    expect(draft).toMatchObject({ status: 'DRAFT', flow: 'WITH_DATA', detectedBy: 'CODE' });
    const removed = draft.edits.map((e) => e.removedText);
    for (const value of SAMPLE_VALUES) expect(removed).toContain(value);
    const stats = await llm.stats();
    expect(stats.byMode.error500 ?? 0, 'the model was asked (and failed)').toBeGreaterThan(0);

    await confirmAsProposed(operatorApi, draft);
    await expectSameRendering(operatorApi, blankId, id, TEMPLATE_PAGES);
  });
});
